CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL CHECK (category IN ('Laboratory','Classroom','Server Room')), building TEXT NOT NULL, floor_label TEXT NOT NULL, capacity INTEGER NOT NULL DEFAULT 0, schedule_label TEXT NOT NULL DEFAULT 'Schedule not configured', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, name TEXT NOT NULL, device_type TEXT NOT NULL, rated_watts NUMERIC(10,2) NOT NULL CHECK (rated_watts >= 0), is_essential BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, occupancy_status TEXT NOT NULL CHECK (occupancy_status IN ('occupied','unoccupied','unknown')), observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), source TEXT NOT NULL CHECK (source IN ('simulated','manual','sensor','camera_inference')), confidence NUMERIC(5,2), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS device_observations (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK (status IN ('on','off','unknown')), observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), source TEXT NOT NULL CHECK (source IN ('simulated','manual','sensor','camera_inference')), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, device_id TEXT REFERENCES devices(id) ON DELETE SET NULL, severity TEXT NOT NULL CHECK (severity IN ('low','medium','high','critical')), status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','verified','resolved','dismissed')), title TEXT NOT NULL, description TEXT NOT NULL, estimated_kwh NUMERIC(10,3) NOT NULL DEFAULT 0, estimated_cost NUMERIC(10,2) NOT NULL DEFAULT 0, recommendation TEXT NOT NULL, verification_status TEXT NOT NULL DEFAULT 'unverified', observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS inspections (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, inspector_label TEXT NOT NULL, occupancy_status TEXT NOT NULL CHECK (occupancy_status IN ('occupied','unoccupied','unknown')), device_notes TEXT NOT NULL, outcome TEXT NOT NULL CHECK (outcome IN ('no_issue','device_switched_off','alert_verified','follow_up_required')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS action_history (id TEXT PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, action TEXT NOT NULL, actor_label TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_rooms_category ON rooms(category);
CREATE INDEX IF NOT EXISTS idx_devices_room ON devices(room_id);
CREATE INDEX IF NOT EXISTS idx_observations_room_time ON observations(room_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_device_observations_device_time ON device_observations(device_id, observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_status_time ON alerts(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_inspections_room_time ON inspections(room_id, created_at DESC);